    friend node operator+(node a, node b)
    {
        return {a.x + b.x, a.y + b.y};
    }

    friend node operator-(node a, node b)
    {
        return {a.x - b.x, a.y - b.y};
    }

    friend ll operator*(node a, node b)
    {
        return 1LL * a.x * b.y - 1LL * a.y * b.x;
    }

    friend bool operator<(node a, node b)
    {
        return a * b < 0;
    }
} a[N], p[N], u[N + 1];

bool cmp(node a, node b)
{
    if (a.y == b.y)
        return a.x < b.x;
    return a.y < b.y;
}

struct tree
{
    node t[N << 2];

    void update(int v)
    {
        if (t[v << 1] * t[v << 1 | 1] == 0)
            t[v] = t[v << 1];
        else
            t[v] = {2000001, 0};
    }

    void build(int v, int l, int r)
    {
        if (l == r)
        {
            t[v] = u[N];
            return;
        }

        int mid = (l + r) >> 1;
        build(v << 1, l, mid);
        build(v << 1 | 1, mid + 1, r);
        update(v);
    }

    void mdf(int v, int l, int r, int x)
    {
        if (l == r)
        {
            t[v] = u[x];
            return;
        }

        int mid = (l + r) >> 1;
        if (x <= mid)
            mdf(v << 1, l, mid, x);
        else
            mdf(v << 1 | 1, mid + 1, r, x);

        update(v);
    }
} T;

