bool cmp(node a, node b)
{
    if (a.y == b.y)
        return a.x < b.x;
    return a.y < b.y;
}
struct tree
{
    node t[N << 2];
    void update(int v)
    {
        if (t[v << 1] * t[v << 1 | 1] == 0)
            t[v] = t[v << 1];
        else
            t[v].x = 2000001, t[v].y = 0;
    }
    void build(int v, int l, int r)
    {
        if (l == r)
        {
            t[v] = u[N];
            return;
        }
        int mid = l + r >> 1;
        build(v << 1, l, mid);
        build(v << 1 | 1, mid + 1, r);
        update(v);
    }
    void mdf(int v, int l, int r, int x)
    {
        if (l == r)
        {
            t[v] = u[x];
            return;
        }
        int mid = l + 1 >> 1;
        if (x <= mid)
            mdf(v << 1, l, mid, x);
        else
            mdf(v << 1 | 1, mid + 1, r, x);
        update(v);
    }
} T;
int n, m, L, pos[N], ans;
pair<node, int> l[N * N >> 1];
bool pd()
{
    for (int i = 1; i <= m; i++)
        if (u[i].x != 0 || u[i].y != 0)
            return 1;
    return 0;
}
int main()
{
    scanf("%d", &n);
    for (int i = 1; i <= n; i++)
        scanf("%d%d", &a[i].x, &a[i].y);

    sort(a + 1, a + n + 1, cmp);
    for (int i = 1; i <= (n + 1) / 2; i++)
        p[i] = a[i] + a[n - i + 1];
    m = (n + 1) / 2 - 1;
    for (int i = 1; i <= m; i++)
        u[i] = p[i + 1] - p[i];
    if (!pd())
    {
        puts("-1");
        //system("pause");
        return 0;
    }

    for (int i = 1; i <= n; i++)
        pos[i] = i;
    L = 0;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j < i; j++)
            l[++L] = make_pair(a[i] - a[j], (i - 1) * n + j - 1);
    sort(l + 1, l + n * (n - 1) / 2 + 1);

    T.build(1, 1, m);
    if (T.t[1].x <= 2000000)
        ans++;
    for (int i = 1; i <= L; i++)
    {
        int a0 = l[i].second / n + 1, a1 = l[i].second % n + 1;

        swap(a[pos[a0]], a[pos[a1]]);
        int p0 = min(pos[a0], n - pos[a0] + 1), p1 = min(pos[a1], n - pos[a1] + 1);
        p[p0] = a[p0] + a[n - p0 + 1];
        p[p1] = a[p1] + a[n - p1 + 1];
        if (p0 > 1)
            u[p0 - 1] = p[p0] - p[p0 - 1], T.mdf(1, 1, m, p0 - 1);
        if (p0 < m)
            u[p0] = p[p0 + 1] - p[p0], T.mdf(1, 1, m, p0);
        if (p1 > 1)
            u[p1 - 1] = p[p1] - p[p1 - 1], T.mdf(1, 1, m, p1 - 1);
        if (p1 < m)
            u[p1] = p[p1 + 1] - p[p1], T.mdf(1, 1, m, p1);
        swap(pos[a0], pos[a1]);
        if (l[i].first * l[i + 1].first != 0 && i < L)
        {

            if (T.t[1].x <= 2000000)
                ans++;
        }
    }
    printf("%d", ans);
    return 0;
}
